package io.tenvyr.control.engine;

import com.fasterxml.jackson.databind.JsonNode;
import com.fasterxml.jackson.databind.node.*;
import io.tenvyr.platform.*;
import java.sql.Connection;
import java.time.*;
import java.util.*;
import static io.tenvyr.control.engine.EngineFacts.*;

/** PostgreSQL step/attempt authority. Scheduling and dispatch handoff commit all-or-none. */
public final class ExecutionService {
  public record Claim(String disposition,ObjectNode logicalStep,ObjectNode attempt) {}
  private final Db db; private final EngineAuthority authority; private final EngineRuntime runtime; private final AgentTransportConfig transport; private final Conditions conditions;
  public ExecutionService(Db db,EngineAuthority authority,EngineRuntime runtime,AgentTransportConfig transport,Conditions conditions){this.db=db;this.authority=authority;this.runtime=runtime;this.transport=transport;this.conditions=conditions;}
  public ObjectNode createExecution(ObjectNode pipeline,JsonNode input){return db.transaction(tx->materializeExecutionWithManager(tx.connection(),pipeline,input,null));}
  public ObjectNode materializeExecutionWithManager(Connection c,ObjectNode pipeline,JsonNode input,Instant deadline){Db tx=Db.on(c);JsonNode budget=authority.validatePipelineBudget(pipeline.get("budget"));ObjectNode plan=Json.object("schemaVersion",1,"steps",pipeline.path("steps"));if(budget!=null&&!budget.isNull())plan.set("budget",budget);ObjectNode definition=Json.object("name",pipeline.get("name"),"version",pipeline.get("version"),"steps",pipeline.get("steps"));if(pipeline.has("description"))definition.set("description",pipeline.get("description"));if(budget!=null&&!budget.isNull())definition.set("budget",budget);String hash=pipeline.hasNonNull("contentHash")&&!pipeline.path("contentHash").asText().isEmpty()?pipeline.path("contentHash").asText():Json.hash(definition);
    ObjectNode execution=tx.insert("executions",Json.object("pipelineId",pipeline.path("id"),"pipelineVersion",pipeline.path("version"),"pipelineHash",hash,"configurationSnapshot",Json.object("schemaVersion",1,"pipelineId",pipeline.path("id"),"pipelineVersion",pipeline.path("version"),"pipelineHash",hash),"status","PENDING","input",input,"startTime",Instant.now().toString(),"authorityDeadlineAt",deadline==null?null:deadline.toString()));
    ObjectNode revision=tx.insert("execution_plan_revisions",Json.object("executionId",execution.path("id"),"revisionNumber",1,"plan",plan,"planHash",Json.hash(plan),"source","pipeline","reason","Initial execution plan snapshot","validationResult",Json.object("valid",true)));
    execution=tx.update("executions",execution.path("id").asText(),Json.object("activePlanRevisionId",revision.path("id")));
    for(JsonNode step:plan.path("steps"))materializeStep(tx,execution.path("id").asText(),step);return execution;
  }
  private void materializeStep(Db tx,String executionId,JsonNode step){tx.execute("INSERT INTO step_executions (\"executionId\",\"stepId\",agent,status,input,attempt,\"maxAttempts\",\"frozenSpecHash\",\"frozenAt\") VALUES (?,?,?,'PENDING',NULL,0,1,NULL,NULL) ON CONFLICT (\"executionId\",\"stepId\") DO NOTHING",executionId,step.path("id").asText(),step.path("agent").asText());}
  public boolean reconcileExecution(String executionId){boolean promoted=db.transaction(tx->tx.execute("UPDATE executions SET status='RUNNING',\"updatedAt\"=now(),\"rowVersion\"=\"rowVersion\"+1 WHERE id=? AND status='PENDING' AND \"activePlanRevisionId\" IS NOT NULL",executionId)==1);
    return db.transaction(tx->{ObjectNode execution=tx.one("SELECT * FROM executions WHERE id=?",executionId);if(execution==null||!execution.hasNonNull("activePlanRevisionId")||TERMINAL_EXECUTION.contains(execution.path("status").asText()))return promoted;ObjectNode revision=tx.one("SELECT * FROM execution_plan_revisions WHERE id=?",execution.path("activePlanRevisionId").asText());if(revision==null)return promoted;JsonNode plan=revision.path("plan");for(JsonNode step:plan.path("steps"))materializeStep(tx,executionId,step);if(!execution.path("status").asText().equals("RUNNING"))return promoted;List<ObjectNode> logical=tx.query("SELECT * FROM step_executions WHERE \"executionId\"=? ORDER BY id",executionId);boolean advanced=false;for(ObjectNode candidate:logical){if(!candidate.path("status").asText().equals("PENDING"))continue;ObjectNode config=step(plan,candidate.path("stepId").asText());if(config==null||!dependenciesResolved(config,logical,plan))continue;ObjectNode locked=tx.one("SELECT * FROM step_executions WHERE id=? AND status='PENDING' FOR UPDATE",candidate.path("id").asText());if(locked==null||tx.exists("SELECT id FROM step_attempts WHERE \"logicalStepId\"=? AND status IN ('CREATED','DISPATCHED','RUNNING','WAITING')",locked.path("id").asText()))continue;tx.update("step_executions",locked.path("id").asText(),Json.object("status","READY","eligibleAt",Instant.now().toString()));advanced=true;}return promoted||advanced;});
  }
  public Claim claimRunnableStep(String executionId,ObjectNode requested,JsonNode input,int maxAttempts,Instant deadline){return db.transaction(tx->{Instant now=Instant.now();ObjectNode logical=tx.one("SELECT * FROM step_executions WHERE \"executionId\"=? AND \"stepId\"=? AND status IN ('READY','RETRYING') AND (\"eligibleAt\" IS NULL OR \"eligibleAt\"<=?) AND (\"nextAttemptAt\" IS NULL OR \"nextAttemptAt\"<=?) FOR UPDATE SKIP LOCKED",executionId,requested.path("id").asText(),now,now);if(logical==null)return null;ObjectNode execution=tx.one("SELECT * FROM executions WHERE id=? FOR UPDATE",executionId);if(execution==null||!execution.path("status").asText().equals("RUNNING"))return null;
    Instant authorityDeadline=instant(execution,"authorityDeadlineAt");if(authorityDeadline!=null&&!authorityDeadline.isAfter(now)){tx.update("step_executions",logical.path("id").asText(),Json.object("status","CANCELLED","error","AUTHORITY_DEADLINE_EXCEEDED","endTime",now.toString(),"nextAttemptAt",null));tx.update("executions",executionId,Json.object("status","FAILED","endTime",now.toString(),"terminationReason","AUTHORITY_DEADLINE_EXCEEDED"));return new Claim("authority_expired",null,null);}Instant attemptDeadline=authorityDeadline!=null&&(deadline==null||authorityDeadline.isBefore(deadline))?authorityDeadline:deadline;
    if(!execution.hasNonNull("activePlanRevisionId"))throw new IllegalStateException("Execution "+executionId+" has no active plan revision");ObjectNode revision=tx.one("SELECT * FROM execution_plan_revisions WHERE id=?",execution.path("activePlanRevisionId").asText());ObjectNode config=revision==null?null:step(revision.path("plan"),requested.path("id").asText());if(config==null)throw new IllegalStateException("Active plan revision does not define step "+requested.path("id").asText());String specHash=Json.hash(config);if(logical.hasNonNull("frozenSpecHash")&&!logical.path("frozenSpecHash").asText().equals(specHash))throw new IllegalStateException("Step "+config.path("id").asText()+" execution specification is frozen");
    validateSelections(config);List<ObjectNode> all=tx.query("SELECT * FROM step_executions WHERE \"executionId\"=?",executionId);if(!dependenciesResolved(config,all,revision.path("plan")))return null;boolean condition=!config.has("condition")||conditions.evaluate(config.get("condition"),Templates.context(execution.get("input"),all));ObjectNode frozen=Json.object("conditionResult",condition,"frozenSpecHash",specHash,"frozenAt",logical.hasNonNull("frozenAt")?logical.get("frozenAt"):now.toString());if(!condition){frozen.put("status","SKIPPED");frozen.put("endTime",now.toString());frozen.putNull("nextAttemptAt");logical=tx.update("step_executions",logical.path("id").asText(),frozen);return new Claim("skipped",logical,null);}
    if(tx.exists("SELECT id FROM step_attempts WHERE \"logicalStepId\"=? AND status IN ('CREATED','DISPATCHED','RUNNING')",logical.path("id").asText()))return null;
    int number=logical.path("attempt").asInt()+1;frozen.put("agent",config.path("agent").asText());frozen.set("input",input);frozen.put("status","RUNNING");frozen.put("attempt",number);frozen.put("maxAttempts",maxAttempts);for(String key:List.of("eligibleAt","nextAttemptAt","output","error","endTime"))frozen.putNull(key);frozen.set("startTime",logical.hasNonNull("startTime")?logical.get("startTime"):Json.value(now.toString()));logical=tx.update("step_executions",logical.path("id").asText(),frozen);
    ObjectNode executor=runtime.resolveExecutor(tx.connection(),config,transport.descriptor(config.path("agent").asText()));String invocationId=logical.path("id").asText()+":"+number;ObjectNode attempt=Json.object("executionId",executionId,"logicalStepId",logical.path("id"),"planRevisionId",revision.path("id"),"attemptNumber",number,"invocationId",invocationId,"frozenSpecHash",specHash,"inputSnapshot",input,"contextSnapshot",null,"executorSnapshot",executor,"status","CREATED","deadlineAt",attemptDeadline==null?null:attemptDeadline.toString());
    EngineAuthority.ClaimContext context;
    try{context=authority.projectContext(tx.connection(),execution,config,executor,revision);attempt.set("contextSnapshot",context.context());attempt.set("efficiency",context.efficiency());}catch(AuthorityFailure error){return failedClaim(tx,execution,logical,config,attempt,"Context projection failed: "+error.code,"projection_failed",now);}
    if(config.path("delegation").asText().equals("observed")&&!transport.supportsObserved(config.path("agent").asText()))return failedClaim(tx,execution,logical,config,attempt,"Runtime for agent \""+config.path("agent").asText()+"\" does not support observed delegation","runtime_capability",now);
    ObjectNode proposal=dispatchProposal(invocationId,executionId,logical.path("id").asText(),number,config.path("agent").asText(),executor.path("kind").asText(),now);JsonNode decision=authority.evaluateDispatch(tx.connection(),proposal);String effect=decision==null?"ALLOW":decision.path("effect").asText("ALLOW");if(effect.equals("DENY"))return failedClaim(tx,execution,logical,config,attempt,"Policy DENY: "+Json.stringify(decision.path("reasons")),"policy_denied",now);
    if(effect.equals("REQUIRE_APPROVAL")){attempt.put("status","WAITING");markEfficiencyUnknown(attempt);attempt=tx.insert("step_attempts",attempt);tx.update("step_executions",logical.path("id").asText(),Json.object("status","WAITING","error","Approval required"));authority.requestApproval(tx.connection(),proposal);return new Claim("approval_required",logical,attempt);}
    if(config.hasNonNull("budget")){try{authority.reserveBudget(tx.connection(),execution,revision,config,attempt);}catch(AuthorityFailure error){return failedClaim(tx,execution,logical,config,attempt,"Budget reservation failed: "+error.code,"budget_insufficient",now);}}
    attempt=tx.insert("step_attempts",attempt);for(String artifactId:context.artifactIds())tx.execute("INSERT INTO artifact_exposures (\"stepAttemptId\",\"artifactId\") VALUES (?,?) ON CONFLICT DO NOTHING",attempt.path("id").asText(),artifactId);
    ObjectNode invocation=Json.object("schemaVersion","1","invocationId",invocationId,"executionId",executionId,"stepExecutionId",logical.path("id"),"stepId",config.path("id"),"target",Json.object("agent",config.path("agent")),"input",input,"attempt",number,"createdAt",now.toString(),"trace",Json.object("traceId",executionId,"correlationId",invocationId),"metadata",Json.object("orchestration",Json.object("maxAttempts",maxAttempts)));if(attemptDeadline!=null)invocation.put("deadlineAt",attemptDeadline.toString());if(context.context()!=null&&!context.context().isNull())invocation.set("context",context.context());JsonNode workspace=runtime.workspaceMetadata(tx.connection(),executionId);if(workspace!=null&&!workspace.isNull())((ObjectNode)invocation.get("metadata")).set("tenvyr",workspace);if(executor.hasNonNull("connection")){JsonNode ref=executor.get("connection");invocation.set("connection",Json.object("connectionId",ref.get("connectionId"),"revisionNumber",ref.get("revisionNumber"),"configHash",ref.get("configHash")));}if(executor.hasNonNull("requestedModelId"))invocation.set("requestedModelId",executor.get("requestedModelId"));tx.insert("dispatch_outbox",Json.object("stepAttemptId",attempt.path("id"),"invocation",invocation));return new Claim("claimed",logical,attempt);
  });}
  private static void markEfficiencyUnknown(ObjectNode attempt){JsonNode efficiency=attempt.get("efficiency");if(efficiency!=null&&efficiency.isObject()&&efficiency.path("session").isObject())((ObjectNode)efficiency.get("session")).put("mode","unknown");}
  private Claim failedClaim(Db tx,ObjectNode execution,ObjectNode logical,ObjectNode config,ObjectNode attempt,String failure,String disposition,Instant now){attempt.put("status","FAILED");markEfficiencyUnknown(attempt);attempt.put("terminalAt",now.toString());attempt.put("error",failure);attempt.put("terminationReason",failure);tx.insert("step_attempts",attempt);settleFailure(tx,execution,logical,config,attempt,failure,now);return new Claim(disposition,logical,attempt);}
  static void settleFailure(Db tx,ObjectNode execution,ObjectNode logical,ObjectNode config,ObjectNode attempt,String failure,Instant now){boolean retry=execution.path("status").asText().equals("RUNNING")&&config!=null&&config.path("onFailure").asText().equals("retry")&&attempt.path("attemptNumber").asInt()<logical.path("maxAttempts").asInt();tx.update("step_executions",logical.path("id").asText(),Json.object("status",retry?"RETRYING":"FAILED","error",failure,"endTime",retry?null:now.toString(),"nextAttemptAt",retry?now.toString():null));if(!retry&&(config==null||!config.path("onFailure").asText().equals("continue"))&&!TERMINAL_EXECUTION.contains(execution.path("status").asText()))tx.update("executions",execution.path("id").asText(),Json.object("status","FAILED","endTime",now.toString(),"terminationReason",failure,"output",Json.object("failedStep",logical.path("stepId"),"error",failure)));}
  public ObjectNode getExecution(String id){return db.one("SELECT * FROM executions WHERE id=?",id);} public List<ObjectNode> listExecutions(){return db.query("SELECT * FROM executions ORDER BY \"createdAt\" DESC");} public List<ObjectNode> getStepExecutions(String id){return db.query("SELECT * FROM step_executions WHERE \"executionId\"=? ORDER BY \"createdAt\",id",id);} public ObjectNode getStepExecution(String id,String stepId){return db.one("SELECT * FROM step_executions WHERE \"executionId\"=? AND \"stepId\"=?",id,stepId);} public ObjectNode getStepExecutionById(String id){return db.one("SELECT * FROM step_executions WHERE id=?",id);} public List<ObjectNode> getStepAttempts(String id){return db.query("SELECT * FROM step_attempts WHERE \"logicalStepId\"=? ORDER BY \"attemptNumber\"",id);} public ObjectNode getAttemptByInvocationId(String id){return db.one("SELECT * FROM step_attempts WHERE \"invocationId\"=?",id);}
  public JsonNode getExecutionPlanSteps(ObjectNode execution){if(execution==null||!execution.hasNonNull("activePlanRevisionId"))throw new IllegalStateException("Execution has no active plan revision");ObjectNode revision=db.one("SELECT * FROM execution_plan_revisions WHERE id=? AND \"executionId\"=?",execution.path("activePlanRevisionId").asText(),execution.path("id").asText());if(revision==null)throw new IllegalStateException("Active plan revision not found");return revision.path("plan").path("steps");}
  public ObjectNode updateExecutionStatus(String id,String status,JsonNode output){return db.transaction(tx->{ObjectNode row=tx.one("SELECT * FROM executions WHERE id=? FOR UPDATE",id);if(row==null)return null;if(TERMINAL_EXECUTION.contains(status)&&TERMINAL_EXECUTION.contains(row.path("status").asText()))return row;ObjectNode fields=Json.object("status",status);if(TERMINAL_EXECUTION.contains(status))fields.put("endTime",Instant.now().toString());if(output!=null)fields.set("output",output);return tx.update("executions",id,fields);});}
  public ObjectNode cancelExecution(String id,String reason){return db.transaction(tx->cancelExecutionWithManager(tx.connection(),id,reason));}
  public ObjectNode cancelExecutionWithManager(Connection c,String id,String reason)throws Exception{Db tx=Db.on(c);List<ObjectNode> attempts=tx.query("SELECT * FROM step_attempts WHERE \"executionId\"=? AND status IN ('CREATED','DISPATCHED','RUNNING','WAITING') ORDER BY id FOR UPDATE",id);List<ObjectNode> steps=tx.query("SELECT * FROM step_executions WHERE \"executionId\"=? ORDER BY id FOR UPDATE",id);ObjectNode execution=tx.one("SELECT * FROM executions WHERE id=? FOR UPDATE",id);if(execution==null)throw new IllegalArgumentException("Execution "+id+" not found");if(TERMINAL_EXECUTION.contains(execution.path("status").asText()))return execution;Instant now=Instant.now();for(ObjectNode attempt:attempts){tx.update("step_attempts",attempt.path("id").asText(),Json.object("status","CANCELLED","terminalAt",now.toString(),"result",null,"error",reason,"terminationReason",reason));authority.releaseBudget(c,attempt.path("invocationId").asText(),"execution cancelled");tx.execute("UPDATE dispatch_outbox SET status='COMPLETED',\"leaseExpiresAt\"=NULL,\"leaseToken\"=NULL WHERE \"stepAttemptId\"=? AND status IN ('PENDING','LEASED','DISPATCHED')",attempt.path("id").asText());}for(ObjectNode step:steps)if(!TERMINAL_STEP.contains(step.path("status").asText()))tx.update("step_executions",step.path("id").asText(),Json.object("status","CANCELLED","error",reason,"endTime",now.toString(),"nextAttemptAt",null,"eligibleAt",null));return tx.update("executions",id,Json.object("status","CANCELLED","endTime",now.toString(),"terminationReason",reason));}
  public List<ObjectNode> listArtifactExposures(String id,int limit){return db.query("SELECT e.* FROM artifact_exposures e JOIN step_attempts a ON a.id=e.\"stepAttemptId\" WHERE a.\"executionId\"=? ORDER BY e.\"createdAt\" LIMIT ?",id,limit);}public int countArtifactExposures(String id){return db.one("SELECT count(*)::int AS count FROM artifact_exposures e JOIN step_attempts a ON a.id=e.\"stepAttemptId\" WHERE a.\"executionId\"=?",id).path("count").asInt();}
  public ObjectNode healthProbe(){try{if(db.one("SELECT to_regclass('migrations') AS name").path("name").isNull())return Json.object("ready",false,"reasonCode","migrations-required");Map<String,Long> applied=new HashMap<>();for(ObjectNode row:db.query("SELECT name,timestamp FROM migrations"))applied.put(Json.text(row,"name"),Json.longValue(row,"timestamp",-1));for(JsonNode migration:Migrator.ledger())if(!Objects.equals(applied.get(Json.text(migration,"name")),migration.path("timestamp").longValue()))return Json.object("ready",false,"reasonCode","migrations-required");return Json.object("ready",true,"reasonCode","ready");}catch(RuntimeException error){return Json.object("ready",false,"reasonCode","postgres-unreachable");}}
  public static ObjectNode dispatchProposal(String invocationId,String executionId,String logicalId,int number,String agent,String kind,Instant now){ObjectNode facts=Json.object("proposalId",invocationId,"actionType","dispatch","scope",Json.object("executionId",executionId,"logicalStepId",logicalId,"attemptNumber",number),"target",Json.object("agent",agent,"executor",kind));facts.put("hash",Json.hash(facts));facts.put("createdAt",now.toString());return facts;}
  public static void validateSelections(JsonNode step){JsonNode metadata=step.path("metadata");JsonNode connection=metadata.get("tenvyrConnectionId"),model=metadata.get("tenvyrModelId");if(connection!=null&&!connection.isNull()&&(!connection.isTextual()||connection.asText().isEmpty()||connection.asText().length()>255||!connection.asText().matches("[A-Za-z0-9_.:-]+")))throw new IllegalArgumentException("Invalid step runtime connection selection");if(model!=null&&!model.isNull()&&(!model.isTextual()||model.asText().length()>256||!model.asText().matches("[A-Za-z0-9][A-Za-z0-9._/\\-:@+]*")))throw new IllegalArgumentException("Invalid step requested model selection");}
}
